def beat(id_,speech,hero,action,before,after,composition,role='participant'):
 q=contract();q.update(hero=hero,primary_action=action,before=before,after=after,purpose=speech,environment=['paper backboard','work surface'],secondary_motion=[],focal_target=hero,exit_overlap=None)
 q['energy']={'dominant_action':action}
 q['art_direction'].update(materials=['printed paper','card supports'],depth_planes=['paper backboard','hero and contact plane'],hero_object=hero,bot_role=role,composition=composition,intentional_irregularity='A corner crop directs attention to the active contact.',environment_mode='physical',environment_justification=None)
 q['performance']={'state':'absent' if role=='absent' else 'focused','target':'' if role=='absent' else 'bot'}
 return {'id':id_,'narration':speech,'quality':q}

def fixture(name,specs,rules,expected,token=None):
 folder=P/'fixtures-clean'/name
 if folder.exists():raise ValueError('preserve previous fixture: '+name)
 beats=[beat('b'+str(i+1),*s) for i,s in enumerate(specs)]
 script=' '.join(b['narration'] for b in beats);words=script.split();start=0;setups=[]
 for i,r in enumerate(rules):
  ids=r['beats'];selected=[b for b in beats if b['id'] in ids];text=' '.join(b['narration'] for b in selected);end=start+len(text.split());art=selected[0]['quality']['art_direction']
  setups.append({'setup_id':'s'+str(i+1),'chapter':'argument','narration_span':{'start_word':start,'end_word':end,'text':text},'semantic_center':r['center'],'visual_rule':r['rule'],'relationship_archetype':r.get('archetype','physical interaction'),'hero':selected[0]['quality']['hero'],'bot_role':art['bot_role'],'continuity_tokens':[token['id']] if token else [],'environment_mode':'physical','palette_family':r.get('palette','warm paper / teal'),'entry_state':selected[0]['quality']['before'],'exit_state':selected[-1]['quality']['after'],'reason_for_persistence':r['persistence'],'planned_reset_after':{'kind':'end' if i==len(rules)-1 else 'hard-cut','reason':r.get('reset','The argument ends in this visible consequence.')},'beat_ids':ids});start=end
 plan={'quality_mode':'motif-gold-v1','script':script,'asset_usage':[{'id':'planning-paper','scope':'production-specific','path':'','metadata_path':'','agent_assisted':True}],'beats':beats,'film_structure':{'version':'structure-1.0','rhetorical_chapters':[{'id':'argument','purpose':'Develop the supplied short argument through visible changes.','narration_span':{'start_word':0,'end_word':len(words),'text':script}}],'setups':setups,'continuity_tokens':[token] if token else []}}
 write(folder/'production-plan.json',plan);write(folder/'expected.json',{'expected':expected,'scope':'Withheld from independent critic. Planning evidence only; no execution/art approval.'});plan_check(plan)

